import random

def partition(l, lo, hi):
    pivot = l[hi]
    i = lo - 1
    for j in range(lo, hi):
        if l[j] <= pivot:
            i += 1
            l[i], l[j] = l[j], l[i]
    l[i+1], l[hi] = l[hi], l[i+1]
    return i + 1

def quickselect(l, lo, hi, k):
    if lo == hi:
        return l[lo]
    pivot_idx = partition(l, lo, hi)
    if k == pivot_idx:
        return l[k]
    elif k < pivot_idx:
        return quickselect(l, lo, pivot_idx-1, k)
    else:
        return quickselect(l, pivot_idx+1, hi, k)

def median(l):
    n = len(l)
    if n % 2 == 0:
        return (quickselect(l, 0, n//2-1, n//2) + quickselect(l, n//2, n-1, n//2)) / 2
    else:
        return quickselect(l, 0, n-1, n//2)
```

